definition.script:
String soloBranchSpec(String branch) {
    String value = branch?.trim() ?: 'main'
    value = value.replaceFirst('^refs/heads/', '').replaceFirst('^origin/', '')
    return value.startsWith('*/') ? value : "*/${value}"
}

pipeline {
    agent { node { label 'built-in' } }
    options {
        skipDefaultCheckout(true)
        disableConcurrentBuilds()
        lock(resource: 'headsling-unity-macos')
        buildDiscarder(logRotator(numToKeepStr: '10'))
        timeout(time: 240, unit: 'MINUTES')
        timestamps()
    }
    parameters {
        choice(name: 'SOURCE_MODE', choices: ['LOCAL_SNAPSHOT', 'GIT'], description: 'Local snapshot includes unpushed source changes; Git uses the selected branch.')
        string(name: 'LOCAL_SOURCE_PATH', defaultValue: '/Users/daisei/HeadGame', description: 'Read-only source for LOCAL_SNAPSHOT. Build caches and credentials are excluded.')
        string(name: 'BRANCH', defaultValue: 'main', description: 'Git branch for GIT mode.')
        choice(name: 'UNITY_VERSION', choices: ['6000.5.1f1'], description: 'Must match the source ProjectVersion.txt.')
        string(name: 'EXPECTED_CONTENT_VERSION', defaultValue: '', description: 'Optional positive version assertion. Blank reads ContentVersion from the source JSON; never changes it.')
        booleanParam(name: 'IOS', defaultValue: true, description: 'Build and verify the standalone iOS solo config catalog.')
        booleanParam(name: 'ANDROID', defaultValue: true, description: 'Build and verify the standalone Android solo config catalog.')
        booleanParam(name: 'PUBLISH', defaultValue: true, description: 'Publish both platform catalogs and raw config to the existing release prefix.')
        booleanParam(name: 'VALIDATE_ONLY', defaultValue: false, description: 'Build and validate locally; overrides PUBLISH and does not use AWS.')
        booleanParam(name: 'CLEAN_LIBRARY', defaultValue: false, description: 'Clear only this independent job workspace Library cache.')
        choice(name: 'AWS_PROFILE', choices: ['mcombatDev'], description: 'Existing AWS CLI profile. Credentials are never copied into the workspace.')
    }
    environment {
        HEADSLING_SOLO_REMOTE_ROOT = 'https://mcombat.s3.ap-northeast-1.amazonaws.com/release/headsling/config/v1'
        HEADSLING_SOLO_DESTINATION = 's3://mcombat/release/headsling/config/v1'
    }
    stages {
        stage('Prepare Source') {
            steps {
                script {
                    env.HEADSLING_SOURCE_MODE = params.SOURCE_MODE ?: 'LOCAL_SNAPSHOT'
                    env.HEADSLING_SOURCE_PROJECT = params.LOCAL_SOURCE_PATH?.trim() ?: '/Users/daisei/HeadGame'
                    env.HEADSLING_IOS = (params.IOS == null ? true : params.IOS).toString()
                    env.HEADSLING_ANDROID = (params.ANDROID == null ? true : params.ANDROID).toString()
                    env.HEADSLING_CLEAN_LIBRARY = (params.CLEAN_LIBRARY ?: false).toString()
                    env.HEADSLING_VALIDATE_ONLY = (params.VALIDATE_ONLY ?: false).toString()
                    env.HEADSLING_PUBLISH = ((params.PUBLISH == null ? true : params.PUBLISH) && !params.VALIDATE_ONLY).toString()
                    env.HEADSLING_AWS_PROFILE = params.AWS_PROFILE ?: 'mcombatDev'
                    if (!(env.HEADSLING_SOURCE_MODE in ['LOCAL_SNAPSHOT', 'GIT'])) {
                        error('SOURCE_MODE must be LOCAL_SNAPSHOT or GIT.')
                    }
                    if (env.HEADSLING_IOS != 'true' && env.HEADSLING_ANDROID != 'true') {
                        error('Select at least one platform.')
                    }
                    if (env.HEADSLING_PUBLISH == 'true' && (env.HEADSLING_IOS != 'true' || env.HEADSLING_ANDROID != 'true')) {
                        error('Publication requires both iOS and Android so shared raw config cannot advance without both catalogs. Use VALIDATE_ONLY for one platform.')
                    }
                    if (env.HEADSLING_AWS_PROFILE != 'mcombatDev') {
                        error('This job uses only the existing mcombatDev AWS profile.')
                    }
                    if (env.HEADSLING_SOURCE_MODE == 'LOCAL_SNAPSHOT') {
                        sh '''#!/bin/bash
set -euo pipefail
test -f "$HEADSLING_SOURCE_PROJECT/tools/ci/prepare-solo-workspace.py"
set -- --source "$HEADSLING_SOURCE_PROJECT" --workspace "$WORKSPACE"
if [ "$HEADSLING_CLEAN_LIBRARY" != 'true' ]; then set -- "$@" --preserve-library; fi
python3 "$HEADSLING_SOURCE_PROJECT/tools/ci/prepare-solo-workspace.py" "$@"
'''
                    } else {
                        checkout([
                            $class: 'GitSCM', branches: [[name: soloBranchSpec(params.BRANCH?.toString())]],
                            doGenerateSubmoduleConfigurations: false,
                            extensions: [[$class: 'LocalBranch', localBranch: '**']],
                            userRemoteConfigs: [[credentialsId: 'bodacheng', url: 'https://github.com/bodacheng/HeadGame.git']]
                        ])
                        sh '''#!/bin/bash
set -euo pipefail
test -f tools/ci/prepare-solo-workspace.py
# Clear source remnants from an earlier LOCAL_SNAPSHOT run while preserving
# ignored Unity caches. Git mode always builds exactly the selected checkout.
git reset --hard HEAD >/dev/null
git clean -fd >/dev/null
if [ "$HEADSLING_CLEAN_LIBRARY" = 'true' ]; then rm -rf "$WORKSPACE/Library"; fi
rm -rf "$WORKSPACE/Logs/SoloContent" "$WORKSPACE/Logs/Jenkins" "$WORKSPACE/ServerData/solo-release" "$WORKSPACE/Builds/SoloContentStates"
python3 tools/ci/prepare-solo-workspace.py --source "$WORKSPACE" --inspect-only
'''
                    }
                }
            }
        }
        stage('Preflight') {
            steps {
                script {
                    def required = ['tools/ci/build-solo-content.sh', 'tools/ci/publish-solo-content.py',
                                    'Assets/Editor/SoloContentBuilder.cs', 'Assets/Scripts/HeadSling/SoloChallengeCatalog.cs']
                    def missing = required.findAll { !fileExists(it) }
                    if (missing) error("Source is missing solo build files: ${missing.join(', ')}.")
                    // Parse with Python rather than requiring a sandbox approval
                    // or the optional pipeline-utility-steps plugin.
                    String receiptMetadata = sh(returnStdout: true, script: '''#!/bin/bash
set -euo pipefail
python3 - <<'PY'
import json, re
with open('Logs/Jenkins/source-snapshot.json', encoding='utf-8') as stream:
    receipt = json.load(stream)
unity = receipt.get('unityVersion')
version = receipt.get('contentVersion')
revision = receipt.get('sourceGitRevision')
dirty = receipt.get('sourceDirty')
dirty_hash = receipt.get('sourceDirtyHash')
if not isinstance(unity, str) or not re.fullmatch(r'[0-9]+[.][0-9]+[.][0-9]+[abfp][0-9]+', unity):
    raise SystemExit('Invalid source Unity version in receipt.')
if type(version) is not int or version < 1:
    raise SystemExit('Invalid source ContentVersion in receipt.')
if not isinstance(revision, str) or not re.fullmatch(r'[0-9a-f]{40}|[0-9a-f]{64}', revision):
    raise SystemExit('Invalid source Git revision in receipt.')
if type(dirty) is not bool or (dirty and (not isinstance(dirty_hash, str) or not re.fullmatch(r'[0-9a-f]{64}', dirty_hash))):
    raise SystemExit('Invalid source dirty fingerprint in receipt.')
for key, value in [('unityVersion', unity), ('contentVersion', version), ('sourceGitRevision', revision),
                   ('sourceDirty', str(dirty).lower()), ('sourceDirtyHash', dirty_hash if dirty else '')]:
    print(str(key) + '=' + str(value))
PY
''').trim()
                    def receipt = [:]
                    receiptMetadata.split('\n').each { line ->
                        def pair = line.split('=', 2)
                        if (pair.length != 2) error('Invalid fixed-key source receipt metadata.')
                        receipt[pair[0]] = pair[1]
                    }
                    boolean sourceDirty = receipt.sourceDirty == 'true'
                    if (env.HEADSLING_SOURCE_MODE == 'GIT' && sourceDirty) {
                        error('Git source must be clean after checkout; refusing mixed source from an earlier workspace run.')
                    }
                    String unity = params.UNITY_VERSION ?: '6000.5.1f1'
                    if (receipt.unityVersion != unity) error("Source requires Unity ${receipt.unityVersion}; selected ${unity}.")
                    String expected = params.EXPECTED_CONTENT_VERSION?.trim()
                    if (expected && (!(expected ==~ /^[1-9][0-9]*$/) || expected != receipt.contentVersion.toString())) {
                        error("EXPECTED_CONTENT_VERSION must match source ContentVersion ${receipt.contentVersion}; source JSON is never overwritten.")
                    }
                    env.HEADSLING_CONTENT_VERSION = receipt.contentVersion.toString()
                    env.HEADSLING_UNITY_EXECUTABLE = "/Applications/Unity/Hub/Editor/${unity}/Unity.app/Contents/MacOS/Unity"
                    env.HEADSLING_SOLO_OUTPUT_ROOT = "ServerData/solo-release/${env.HEADSLING_CONTENT_VERSION}"
                    env.HEADSLING_GIT_REVISION = receipt.sourceGitRevision + (sourceDirty ? ":dirty:${receipt.sourceDirtyHash}" : '')
                    env.HEADSLING_CI_RUN_ID = env.BUILD_TAG
                    currentBuild.description = "Solo config: ${env.HEADSLING_CONTENT_VERSION}\nSource: ${env.HEADSLING_SOURCE_MODE}\nGit: ${receipt.sourceGitRevision}\nDirty: ${sourceDirty ? receipt.sourceDirtyHash : 'no'}\nPublish: ${env.HEADSLING_PUBLISH}"
                }
                sh '''#!/bin/bash
set -euo pipefail
test -x "$HEADSLING_UNITY_EXECUTABLE"
TASK_EDITOR_ROOT="${HEADSLING_UNITY_EXECUTABLE%/Unity.app/Contents/MacOS/Unity}"
if [ "$HEADSLING_IOS" = 'true' ]; then test -d "$TASK_EDITOR_ROOT/PlaybackEngines/iOSSupport"; fi
if [ "$HEADSLING_ANDROID" = 'true' ]; then test -d "$TASK_EDITOR_ROOT/PlaybackEngines/AndroidPlayer"; fi
command -v python3 >/dev/null
if [ "$HEADSLING_PUBLISH" = 'true' ]; then
    command -v aws >/dev/null
    aws configure list --profile "$HEADSLING_AWS_PROFILE" >/dev/null
    aws sts get-caller-identity --profile "$HEADSLING_AWS_PROFILE" --no-cli-pager >/dev/null
fi
mkdir -p Logs/SoloContent
'''
            }
        }
        stage('Build and Verify Solo Assets') {
            steps {
                sh '''#!/bin/bash
set -euo pipefail
set --
if [ "$HEADSLING_ANDROID" = 'true' ]; then set -- "$@" Android; fi
if [ "$HEADSLING_IOS" = 'true' ]; then set -- "$@" iOS; fi
if bash tools/ci/build-solo-content.sh "$@" > Logs/SoloContent/validation.log 2>&1; then
    cat Logs/SoloContent/validation.log
else
    TASK_STATUS=$?
    cat Logs/SoloContent/validation.log
    exit "$TASK_STATUS"
fi
'''
            }
        }
        stage('Publish Solo Assets') {
            when { expression { env.HEADSLING_PUBLISH == 'true' } }
            steps {
                sh '''#!/bin/bash
set -euo pipefail
if python3 tools/ci/publish-solo-content.py "$HEADSLING_SOLO_OUTPUT_ROOT" \
    --targets Android iOS --profile "$HEADSLING_AWS_PROFILE" \
    --destination "$HEADSLING_SOLO_DESTINATION" --publish \
    > Logs/SoloContent/publication.log 2>&1; then
    cat Logs/SoloContent/publication.log
else
    TASK_STATUS=$?
    cat Logs/SoloContent/publication.log
    exit "$TASK_STATUS"
fi
'''
            }
        }
    }
    post {
        always {
            archiveArtifacts artifacts: 'Logs/Jenkins/source-snapshot.json,Logs/SoloContent/**,ServerData/solo-release/**,Builds/SoloContentStates/**',
                allowEmptyArchive: true, fingerprint: true, followSymlinks: false
        }
    }
}
